import { createServerFn } from "@tanstack/react-start"

import type { Instrument } from "./instruments"
import type { Person } from "./people"

export const loadInstruments = createServerFn({ method: "GET" })
  .validator((query: string) => query)
  .handler(async ({ data }): Promise<Instrument[]> => {
    const { filterInstruments } = await import("./instruments")
    return filterInstruments(data)
  })

export const loadInstrument = createServerFn({ method: "GET" })
  .validator((symbol: string) => symbol)
  .handler(async ({ data }): Promise<Instrument | null> => {
    const { getInstrumentBySymbol } = await import("./instruments")
    return getInstrumentBySymbol(data)
  })

export const loadCurrentPerson = createServerFn({ method: "POST" }).handler(
  async (): Promise<Person | null> => {
    const { getCurrentPerson } = await import("./session")
    return getCurrentPerson()
  }
)

export const loadPeople = createServerFn({ method: "GET" }).handler(
  async (): Promise<Person[]> => {
    const { PEOPLE } = await import("./people")
    return [...PEOPLE]
  }
)

export const selectPerson = createServerFn({ method: "POST" })
  .validator((personId: string) => personId)
  .handler(async ({ data }): Promise<Person> => {
    const { signIn } = await import("./session")
    return signIn(data)
  })

export const clearPerson = createServerFn({ method: "POST" }).handler(
  async (): Promise<boolean> => {
    const { signOut } = await import("./session")
    signOut()
    return true
  }
)
import { describe, expect, it } from "vitest"

import { filterInstruments, getInstrumentBySymbol } from "./instruments"

describe("instrument data", () => {
  it("loads the fixture and looks up symbols", () => {
    expect(filterInstruments("")).toHaveLength(88)
    expect(getInstrumentBySymbol("EUR/USD")).toMatchObject({
      name: "Euro US Dollar",
      decimals: 4,
    })
    expect(getInstrumentBySymbol("UNKNOWN")).toBeNull()
  })
})
import rawInstruments from "../data/instruments.json"

type AssetClass = "bond" | "commodity" | "currency" | "etf" | "index" | "share"

export interface Instrument {
  symbol: string
  name: string
  asset_class: AssetClass
  exchange: string
  currency: string | null
  decimals: number
  last_price: number
}

const instruments: readonly Instrument[] = rawInstruments.map((instrument) => ({
  symbol: instrument.symbol,
  name: instrument.name,
  asset_class: instrument.asset_class as AssetClass,
  exchange: instrument.exchange,
  currency: instrument.currency,
  decimals: instrument.decimals,
  last_price: instrument.last_price,
}))

export function filterInstruments(query: string): Instrument[] {
  const normalizedQuery = query.trim().toLowerCase()
  if (!normalizedQuery) {
    return [...instruments]
  }

  return instruments.filter(
    (instrument) =>
      instrument.symbol.toLowerCase().includes(normalizedQuery) ||
      instrument.name.toLowerCase().includes(normalizedQuery)
  )
}

export function getInstrumentBySymbol(symbol: string): Instrument | null {
  return instruments.find((instrument) => instrument.symbol === symbol) ?? null
}
export interface Person {
  id: string
  displayName: string
  email: string
}

export const PEOPLE: readonly Person[] = [
  {
    id: "person-ava",
    displayName: "Ava Morgan",
    email: "ava.morgan@example.com",
  },
  {
    id: "person-liam",
    displayName: "Liam Chen",
    email: "liam.chen@example.com",
  },
]

export function findPerson(id: string): Person | null {
  return PEOPLE.find((person) => person.id === id) ?? null
}
import {
  deleteCookie,
  getCookie,
  setCookie,
} from "@tanstack/react-start/server"
import type { Person } from "./people"
import { findPerson } from "./people"

const PERSON_COOKIE = "person_id"

export function getCurrentPerson(): Person | null {
  const personId = getCookie(PERSON_COOKIE)
  return personId ? findPerson(personId) : null
}

export function signIn(personId: string): Person {
  const person = findPerson(personId)
  if (!person) {
    throw new Error("Unknown person")
  }

  setCookie(PERSON_COOKIE, person.id, {
    httpOnly: true,
    path: "/",
    sameSite: "lax",
  })

  return person
}

export function signOut(): void {
  deleteCookie(PERSON_COOKIE, { path: "/" })
}
import { TanStackDevtools } from "@tanstack/react-devtools"
import {
  createRootRoute,
  HeadContent,
  Outlet,
  Scripts,
} from "@tanstack/react-router"
import { TanStackRouterDevtoolsPanel } from "@tanstack/react-router-devtools"

import { SiteHeader } from "@/components/site-header"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty"
import { loadCurrentPerson } from "@/server/functions"
import appCss from "../styles.css?url"

export const Route = createRootRoute({
  loader: () => loadCurrentPerson(),
  head: () => ({
    meta: [
      {
        charSet: "utf-8",
      },
      {
        name: "viewport",
        content: "width=device-width, initial-scale=1",
      },
      {
        name: "color-scheme",
        content: "light dark",
      },
      {
        title: "Market Desk",
      },
    ],
    links: [
      {
        rel: "stylesheet",
        href: appCss,
      },
    ],
  }),
  notFoundComponent: () => (
    <Empty>
      <EmptyHeader>
        <EmptyTitle>
          <h1>Page not found</h1>
        </EmptyTitle>
        <EmptyDescription>The requested page does not exist.</EmptyDescription>
      </EmptyHeader>
    </Empty>
  ),
  component: RootComponent,
  shellComponent: RootDocument,
})

function RootComponent() {
  const person = Route.useLoaderData()

  return (
    <>
      <SiteHeader person={person} />
      <main className="mx-auto w-full max-w-7xl px-4 py-10 sm:px-8">
        <Outlet />
      </main>
    </>
  )
}

// Set the theme and register the shortcut before hydration (and the first paint).
const initializeTheme = `
  const systemTheme = matchMedia("(prefers-color-scheme: dark)");
  let saved;
  try { saved = localStorage.getItem("theme"); } catch {}

  const applyTheme = (dark) => {
    document.documentElement.classList.toggle("dark", dark);
    document.querySelectorAll('meta[name="color-scheme"]').forEach((meta) => {
      meta.content = dark ? "dark" : "light";
    });
  };
  applyTheme(saved === "dark" || (saved !== "light" && systemTheme.matches));

  systemTheme.addEventListener("change", (event) => {
    try { saved = localStorage.getItem("theme"); } catch { saved = undefined; }
    if (saved !== "dark" && saved !== "light") applyTheme(event.matches);
  });

  const toggleTheme = () => {
    const dark = !document.documentElement.classList.contains("dark");
    applyTheme(dark);
    saved = dark ? "dark" : "light";
    try { localStorage.setItem("theme", saved); } catch {}
  };

  window.addEventListener("click", (event) => {
    if (
      event.target instanceof Element &&
      event.target.closest("[data-theme-toggle]")
    ) toggleTheme();
  });

  window.addEventListener("keydown", (event) => {
    if (
      event.key.toLowerCase() !== "d" || event.repeat ||
      event.altKey || event.ctrlKey || event.metaKey ||
      (event.target instanceof Element && event.target.closest(
        'input, textarea, select, [contenteditable], [role="textbox"]'
      ))
    ) return;

    toggleTheme();
  });
`

function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <HeadContent />
        {/* biome-ignore lint/security/noDangerouslySetInnerHtml: The script contains a static, application-defined theme initializer. */}
        <script dangerouslySetInnerHTML={{ __html: initializeTheme }} />
      </head>
      <body className="antialiased">
        {children}
        <TanStackDevtools
          config={{
            position: "bottom-right",
          }}
          plugins={[
            {
              name: "Tanstack Router",
              render: <TanStackRouterDevtoolsPanel />,
            },
          ]}
        />
        <Scripts />
      </body>
    </html>
  )
}
