import { Badge } from "@/components/ui/badge"
import { formatDecimal } from "@/lib/alert-rules"
import type { Alert } from "@/server/alerts"

/** Active or Paused, as a badge. */
export function AlertStateBadge({ state }: { state: Alert["state"] }) {
  return state === "active" ? (
    <Badge variant="secondary">Active</Badge>
  ) : (
    <Badge variant="outline">Paused</Badge>
  )
}

/**
 * What is known about the Alert's Matches. With no Checking System connected
 * nothing is known yet, so this never claims "no matches".
 */
export function AlertCheckStatus({ alert }: { alert: Alert }) {
  if (alert.latestMatch) {
    return (
      <span className="text-sm text-muted-foreground">
        Last matched{" "}
        <time dateTime={alert.latestMatch.matchedAt}>
          {alert.latestMatch.matchedAt}
        </time>{" "}
        at {formatDecimal(alert.latestMatch.price, alert.decimals)}
      </span>
    )
  }
  return <span className="text-sm text-muted-foreground">Not yet checked</span>
}
  deleteAlert,
  loadAlert,
  loadAlertFormContext,
  updateAlert,
} from "@/server/functions"

