        ? loadAlert({ data: params.alertId })
        : null,
      loadAlertFormContext(),
    ])
    return { alert, context }
  },
  component: AlertPage,
})

function AlertPage() {
  const { alert, context } = Route.useLoaderData()

  // Foreign and missing Alerts look exactly the same.
  if (!alert) {
    return (
